  1→//! Configuration file discovery and loading.
  2→//!
  3→//! This module handles finding and loading configuration files from
  4→//! various locations in the correct priority order.
  5→
  6→use crate::config::extends::ExtendsResolver;
  7→use crate::config::merger::merge_configs;
  8→use crate::config::schema::BivvyConfig;
  9→use crate::error::{BivvyError, Result};
 10→use std::fs;
 11→use std::path::{Path, PathBuf};
 12→
 13→/// Paths to configuration files in priority order (later overrides earlier).
 14→///
 15→/// Merge order:
 16→/// 1. Remote base configs (from `extends:`)
 17→/// 2. User global config (`~/.bivvy/config.yml`)
 18→/// 3. Project config (`.bivvy/config.yml`)
 19→/// 4. Local overrides (`.bivvy/config.local.yml`)
 20→#[derive(Debug, Clone)]
 21→pub struct ConfigPaths {
 22→    /// Remote base config (if extends: is used)
 23→    pub extends: Vec<PathBuf>,
 24→
 25→    /// User's global config: ~/.bivvy/config.yml
 26→    pub user_global: Option<PathBuf>,
 27→
 28→    /// Project config: .bivvy/config.yml
 29→    pub project: Option<PathBuf>,
 30→
 31→    /// Local overrides: .bivvy/config.local.yml
 32→    pub project_local: Option<PathBuf>,
 33→}
 34→
 35→impl ConfigPaths {
 36→    /// Discover config files for the given project root.
 37→    pub fn discover(project_root: &Path) -> Self {
 38→        Self {
 39→            extends: Vec::new(), // Populated later after parsing project config
 40→            user_global: Self::find_user_global(),
 41→            project: Self::find_project_config(project_root),
 42→            project_local: Self::find_project_local(project_root),
 43→        }
 44→    }
 45→
 46→    /// Find user's global config at ~/.bivvy/config.yml
 47→    fn find_user_global() -> Option<PathBuf> {
 48→        let path = dirs::home_dir()?.join(".bivvy").join("config.yml");
 49→        if path.exists() {
 50→            Some(path)
 51→        } else {
 52→            None
 53→        }
 54→    }
 55→
 56→    /// Find project config at .bivvy/config.yml
 57→    fn find_project_config(project_root: &Path) -> Option<PathBuf> {
 58→        let path = project_root.join(".bivvy").join("config.yml");
 59→        if path.exists() {
 60→            Some(path)
 61→        } else {
 62→            None
 63→        }
 64→    }
 65→
 66→    /// Find local overrides at .bivvy/config.local.yml
 67→    fn find_project_local(project_root: &Path) -> Option<PathBuf> {
 68→        let path = project_root.join(".bivvy").join("config.local.yml");
 69→        if path.exists() {
 70→            Some(path)
 71→        } else {
 72→            None
 73→        }
 74→    }
 75→
 76→    /// Returns all existing config paths in merge order.
 77→    pub fn all_existing(&self) -> Vec<&PathBuf> {
 78→        let mut paths = Vec::new();
 79→
 80→        for p in &self.extends {
 81→            paths.push(p);
 82→        }
 83→
 84→        if let Some(p) = &self.user_global {
 85→            paths.push(p);
 86→        }
 87→
 88→        if let Some(p) = &self.project {
 89→            paths.push(p);
 90→        }
 91→
 92→        if let Some(p) = &self.project_local {
 93→            paths.push(p);
 94→        }
 95→
 96→        paths
 97→    }
 98→
 99→    /// Check if any project config exists.
100→    pub fn has_project_config(&self) -> bool {

  1→//! Platform-specific shell detection.
  2→
  3→use std::path::PathBuf;
  4→
  5→/// Information about the current shell environment.
  6→#[derive(Debug, Clone)]
  7→pub struct ShellInfo {
  8→    /// Shell executable path.
  9→    pub executable: PathBuf,
 10→
 11→    /// Shell name (bash, zsh, fish, powershell, cmd).
 12→    pub name: ShellType,
 13→
 14→    /// Config files that affect this shell.
 15→    pub config_files: Vec<PathBuf>,
 16→
 17→    /// Command to reload the shell.
 18→    pub reload_command: String,
 19→}
 20→
 21→/// Known shell types.
 22→#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 23→pub enum ShellType {
 24→    Bash,
 25→    Zsh,
 26→    Fish,
 27→    PowerShell,
 28→    Cmd,
 29→    Unknown,
 30→}
 31→
 32→impl ShellType {
 33→    /// Parse shell type from executable name.
 34→    pub fn from_executable(exe: &str) -> Self {
 35→        let name = std::path::Path::new(exe)
 36→            .file_stem()
 37→            .and_then(|s| s.to_str())
 38→            .unwrap_or("")
 39→            .to_lowercase();
 40→
 41→        match name.as_str() {
 42→            "bash" => ShellType::Bash,
 43→            "zsh" => ShellType::Zsh,
 44→            "fish" => ShellType::Fish,
 45→            "powershell" | "pwsh" => ShellType::PowerShell,
 46→            "cmd" => ShellType::Cmd,
 47→            _ => ShellType::Unknown,
 48→        }
 49→    }
 50→}
 51→
 52→/// Detect the current shell environment.
 53→pub fn detect_shell() -> ShellInfo {
 54→    let executable = get_shell_executable();
 55→    let shell_type = ShellType::from_executable(&executable.to_string_lossy());
 56→
 57→    ShellInfo {
 58→        executable: executable.clone(),
 59→        name: shell_type,
 60→        config_files: get_config_files(shell_type),
 61→        reload_command: get_reload_command(shell_type, &executable),
 62→    }
 63→}
 64→
 65→fn get_shell_executable() -> PathBuf {
 66→    if cfg!(target_os = "windows") {
 67→        std::env::var("COMSPEC")
 68→            .map(PathBuf::from)
 69→            .unwrap_or_else(|_| PathBuf::from("cmd.exe"))
 70→    } else {
 71→        std::env::var("SHELL")
 72→            .map(PathBuf::from)
 73→            .unwrap_or_else(|_| PathBuf::from("/bin/sh"))
 74→    }
 75→}
 76→
 77→fn get_config_files(shell_type: ShellType) -> Vec<PathBuf> {
 78→    let home = dirs::home_dir().unwrap_or_default();
 79→
 80→    match shell_type {
 81→        ShellType::Bash => vec![
 82→            home.join(".bashrc"),
 83→            home.join(".bash_profile"),
 84→            home.join(".profile"),
 85→        ],
 86→        ShellType::Zsh => vec![
 87→            home.join(".zshrc"),
 88→            home.join(".zprofile"),
 89→            home.join(".zshenv"),
 90→        ],
 91→        ShellType::Fish => vec![home.join(".config/fish/config.fish")],
 92→        ShellType::PowerShell => {
 93→            if let Some(docs) = dirs::document_dir() {
 94→                vec![
 95→                    docs.join("PowerShell/Microsoft.PowerShell_profile.ps1"),
 96→                    docs.join("WindowsPowerShell/Microsoft.PowerShell_profile.ps1"),
 97→                ]
 98→            } else {
 99→                vec![]
100→            }

