#[test]
fn cli_run_accepts_workflow_flag() -> Result<(), Box<dyn std::error::Error>> {
    let temp = setup_project(SIMPLE_CONFIG);
    let mut cmd = Command::new(cargo_bin("bivvy"));
    cmd.current_dir(temp.path());
    cmd.args(["run", "--workflow", "custom", "--dry-run"]);
    cmd.assert()
        .success()
