    #[test]
    fn dry_run_with_ui_does_not_execute() {
        let temp = TempDir::new().unwrap();
        let marker = temp.path().join("executed.txt");

        let config: BivvyConfig = serde_yaml::from_str(
            r#"
            workflows:
              default:
                steps: [dangerous]
